glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform GridFlipParams {
  vec4 gridInfo;
  vec4 flipInfo;
};
float easeInOut(float t) {
  return t < 0.5 ? 2.0 * t * t : 1.0 - pow(-2.0 * t + 2.0, 2.0) / 2.0;
}
vec4 frag () {
  vec4 o = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  float cols     = gridInfo.x;
  float rows     = gridInfo.y;
  float prog     = gridInfo.z;
  float flipAng  = gridInfo.w;
  float stagger  = flipInfo.x;
  float glow     = flipInfo.y;
  if (prog <= 0.001) {
    o *= color;
    return o;
  }
  vec2 uv = uv0;
  vec2 grid = vec2(cols, rows);
  vec2 cell = floor(uv * grid);
  vec2 cellFract = fract(uv * grid);
  float maxDiag = cols + rows - 2.0;
  float diag = (cell.x + cell.y) / max(maxDiag, 1.0);
  float cellDuration = max(1.0 - stagger, 0.01);
  float cellStart = diag * stagger;
  float cellProg = clamp((prog - cellStart) / cellDuration, 0.0, 1.0);
  float t = easeInOut(cellProg);
  if (t <= 0.001) {
    o = CCSampleWithAlphaSeparated(cc_spriteTexture, uv);
    o *= color;
    return o;
  }
  if (t >= 0.999) {
    o = vec4(0.0, 0.0, 0.0, 0.0);
    return o;
  }
  float angle = t * radians(flipAng);
  float cosA = cos(angle);
  float edgeFactor = 1.0 - abs(cosA);
  float gapWidth = 0.04 * edgeFactor;
  if (cellFract.x < gapWidth || cellFract.x > 1.0 - gapWidth ||
      cellFract.y < gapWidth || cellFract.y > 1.0 - gapWidth) {
    o = vec4(0.0, 0.0, 0.0, 0.0);
    return o;
  }
  float localY = cellFract.y - 0.5;
  float scaleY = abs(cosA);
  if (scaleY < 0.005) {
    float lineAlpha = 1.0 - smoothstep(0.0, 0.02, abs(localY));
    o = CCSampleWithAlphaSeparated(cc_spriteTexture, uv);
    o.rgb *= 0.6;
    o.a *= lineAlpha * 0.3;
    o *= color;
    return o;
  }
  float remappedY = localY / scaleY;
  if (abs(remappedY) > 0.5) {
    o = vec4(0.0, 0.0, 0.0, 0.0);
    return o;
  }
  float newCellFractY = remappedY + 0.5;
  vec2 newUV = (cell + vec2(cellFract.x, newCellFractY)) / grid;
  o = CCSampleWithAlphaSeparated(cc_spriteTexture, newUV);
  float alpha = cosA >= 0.0 ? smoothstep(0.0, 0.35, cosA) : 0.0;
  o.a *= alpha;
  float lighting = 0.5 + 0.5 * max(cosA, 0.0);
  o.rgb *= lighting;
  float edgeDist = min(min(cellFract.x, 1.0 - cellFract.x), min(cellFract.y, 1.0 - cellFract.y));
  float edgeGlow = 1.0 - smoothstep(0.0, 0.15, edgeDist);
  float glowFactor = glow * edgeFactor * edgeGlow;
  o.rgb += vec3(1.0, 0.95, 0.85) * glowFactor * o.a;
  o *= color;
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

